def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform horizontal bands encode a vertical cycle. Zero bands are blank.
    if all(len(set(row)) == 1 for row in grid):
        bands = [(r, row[0]) for r, row in enumerate(grid) if row[0] != 0]
        period = len(bands)
        phase = {r % period: color for r, color in bands}
        return [[phase[r % period]] * w for r in range(h)]

    # Diagonal fragments encode a color cycle whose length is the number of
    # occupied diagonal offsets.
    offsets = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                offsets[c - r] = color
    period = len(offsets)
    phase = {offset % period: color for offset, color in offsets.items()}
    return [[phase[(c - r) % period] for c in range(w)] for r in range(h)]
